    <xsd:restriction base="xsd:string">
      <xsd:enumeration value="axisRow"/>
      <xsd:enumeration value="axisCol"/>
      <xsd:enumeration value="axisPage"/>
      <xsd:enumeration value="axisValues"/>
    </xsd:restriction>
