// Small filled orange square used as a bullet/marker
function addSquareMarker(slide, x, y, size = 0.09) {
    slide.addShape(pres.shapes.RECTANGLE, {
        x, y, w: size, h: size,
        fill: { color: ACCENT }, line: { type: "none" }
    });
}

