  brown:        "2B1D12",
  brownDk:      "3A2615",
  brownDk2:     "5A3A20",
  brownMid:     "4A3220",
  caramel:      "8A4A18",
  caramel2:     "D8A050",
  caramel3:     "F0D090",
  caramel4:     "D8A86C",
  cocoa:        "3A2615",
  butterPat:    "E8D4A8",
  marble:       "ECEAD8",
  sage:         "4A5734",
  sage2:        "5A6A3A",
  sageLite:     "7A8A4E",
  creamHi:      "FAECC8",
  creamHi2:     "FAEBC8",
  paleSand:     "F0E2C2",
  pendBulb:     "FFE9A8",
  pendShadow:   "28190A",
  ceilingTrim:  "8A5A30",
  floor:        "5A3A20",
  goldGlow:     "E8C878",
