  const phaseColors = ["9A9A8E", "3F5E2A", "2C4A2B", "C26A33", "8A4A22", "1B2420"];
  const phaseByQ = [0, 0, 1, 1, 1, 1, 3, 3, 3, 4, 5, 5];
  // Note: slide shows grey at Y2 Q3, dark green at Y2 Q4 (Paper 1 submission start),
