const PptxGenJS = require('pptxgenjs');

// ---------------------------------------------------------------------------
// Chart images (embedded as base64 so this file is self-contained)
// ---------------------------------------------------------------------------
const IMG_CURVE       = 'data:image/png;base64,PLACEHOLDER';
const IMG_CALIBRATION = 'data:image/png;base64,PLACEHOLDER';

