  s.addText("the mat.",
    { x: 1.04, y: 5.30, w: 11.00, h: 2.20, fontFace: F_HEAD, fontSize: 130, bold: true, italic: true, color: GOLD, valign: "top", margin: 0, fit: "shrink" });

