  addTextBox(slide, 1.0417, 1.625, 18.4542, 0.7349, [{"runs": [{"text": "A Town Born on the Railroad", "options": {"fontSize": 48.0, "bold": true, "color": "3A2416", "fontFace": "Arial", "charSpacing": -0.48}}], "align": "left", "lineSpacingPct": 104.0}], "t");
