  addTextBox(slide, 1.0417, 3.0994, 15.0208, 1.5075, [{"runs": [{"text": "In 1849, a country doctor named ", "options": {"fontSize": 25.5, "color": "4A3224", "fontFace": "Arial"}}, {"text": "Bartlett Durham ", "options": {"fontSize": 25.5, "bold": true, "color": "4A3224", "fontFace": "Arial"}}, {"text": "donated four acres of land for a new stop on the North Carolina Railroad. Trains rumbled through, a tiny depot grew into a village, and \u2014 almost by accident \u2014 the town took his name.", "options": {"fontSize": 25.5, "color": "4A3224", "fontFace": "Arial"}}], "align": "left", "lineSpacingPct": 138.0}], "t");
