  addTextBox(slide, 1.0417, 2.216, 8.1542, 1.4281, [{"runs": [{"text": "Durham Bulls & America's Pastime", "options": {"fontSize": 48.0, "bold": true, "color": "3A2416", "fontFace": "Arial", "charSpacing": -0.48}}], "align": "left", "lineSpacingPct": 104.0}], "t");
  addRect(slide, { x: 1.0417, y: 3.9357, w: 1.25, h: 0.0312, fill: "8A3A2A" });
  addTextBox(slide, 1.0417, 4.3836, 8.1542, 2.9733, [{"runs": [{"text": "Named for the same bull on the tobacco tins, the ", "options": {"fontSize": 21.68, "color": "4A3224", "fontFace": "Arial"}}, {"text": "Durham Bulls ", "options": {"fontSize": 21.68, "bold": true, "color": "4A3224", "fontFace": "Arial"}}, {"text": "baseball team took the field in 1902 and never left. A 1988 Hollywood movie made them legendary, and today the team plays at the Durham Bulls Athletic Park \u2014 with a giant snorting bull in left field.", "options": {"fontSize": 21.68, "color": "4A3224", "fontFace": "Arial"}}], "align": "left", "lineSpacingPct": 138.0}], "t");
  addRect(slide, { x: 1.0417, y: 7.8153, w: 2.3055, h: 0.0312, fill: "8A3A2A" });
