  addTextBox(slide, 6.6527, 8.0549, 2.3888, 0.9167, [{"runs": [{"text": "10k+", "options": {"fontSize": 63.0, "bold": true, "color": "3A2416", "fontFace": "Arial"}}], "align": "left", "lineSpacingPct": 100.0}], "t");
