  // Neck highlight
  s.addShape("roundRect", { x: cx - 0.5, y: cy - 0.6, w: 1.0, h: 0.9,
    fill: { color: C.parchmentLite }, line: { color: C.parchmentLite }, rectRadius: 0.1 });

  // Head (large circle)
