    catAxisLabelColor: C.text, catAxisLabelFontSize: 10,
    showTitle: true, title: "Turnover Intent (%) vs. Doc Hours per Shift (hrs)", titleColor: C.muted, titleFontSize: 10,
    valAxisLabelColor: C.muted, valAxisLabelFontSize: 10,
