  slide.addText('FALL LINE', { x: 0.9792, y: 0.5833, w: 1.765, h: 0.3781, align: 'left', valign: 'top', margin: [2.0, 2.0, 2.0, 2.0], isTextBox: true, fontSize: 18.0, charSpacing: 2.16, color: '0B1220', fontFace: 'Arial' });
  slide.addText('CHAPTER IV \xB7 PEDAGOGY', { x: 15.4666, y: 0.5833, w: 3.985, h: 0.3781, align: 'left', valign: 'top', margin: [2.0, 2.0, 2.0, 2.0], isTextBox: true, fontSize: 18.0, charSpacing: 2.16, color: '0B1220', fontFace: 'Arial' });
  slide.addText('THE METHOD', { x: 0.75, y: 10.3802, w: 2.0361, h: 0.3781, align: 'left', valign: 'top', margin: [2.0, 2.0, 2.0, 2.0], isTextBox: true, fontSize: 18.0, charSpacing: 2.16, color: '0B1220', fontFace: 'Arial' });
  slide.addText('05 / 08', { x: 18.2755, y: 10.3802, w: 1.395, h: 0.3781, align: 'left', valign: 'top', margin: [2.0, 2.0, 2.0, 2.0], isTextBox: true, fontSize: 18.0, charSpacing: 2.16, color: '0B1220', fontFace: 'Arial' });
  slide.addText('The Method.', { x: 1.25, y: 1.6667, w: 4.0104, h: 2.4667, align: 'left', valign: 'top', margin: [2.0, 2.0, 2.0, 2.0], isTextBox: true, fontSize: 43.75, charSpacing: -0.87, italic: true, color: '0B1220', fontFace: 'Arial', lineSpacingMultiple: 0.95 });
  slide.addText('A four-part practice built over fifteen seasons. Every student, every level, same four movements \u2014 refined to the rider in front of us.', { x: 5.3104, y: 2.3503, w: 13.4397, h: 1.7831, align: 'right', valign: 'top', margin: [2.0, 2.0, 2.0, 2.0], isTextBox: true, fontSize: 21.0, color: '454A52', fontFace: 'Arial', lineSpacingMultiple: 1.45 });
  slide.addShape(pres.shapes.RECTANGLE, { x: 1.25, y: 4.7917, w: 17.5, h: 0.0104, fill: { color: '0B1220', transparency: 82.0 }, line: { type: 'none' } });
  slide.addShape(pres.shapes.RECTANGLE, { x: 5.6146, y: 4.8021, w: 0.0104, h: 4.8333, fill: { color: '0B1220', transparency: 82.0 }, line: { type: 'none' } });
  slide.addText('Movement 01', { x: 1.25, y: 5.2604, w: 4.0664, h: 0.3781, align: 'left', valign: 'top', margin: [2.0, 2.0, 2.0, 2.0], isTextBox: true, fontSize: 18.0, charSpacing: 3.6, color: '74767B', fontFace: 'Arial' });
  slide.addText('Stance', { x: 1.25, y: 5.8385, w: 4.0664, h: 0.6333, align: 'left', valign: 'top', margin: [2.0, 2.0, 2.0, 2.0], isTextBox: true, fontSize: 39.0, charSpacing: -0.39, italic: true, color: '0B1220', fontFace: 'Arial', lineSpacingMultiple: 1.0 });
  slide.addText('Before the first turn, the first breath. Board under ribs, weight stacked, shoulders quiet. Everything downstream is built here.', { x: 1.25, y: 6.6302, w: 4.3146, h: 1.9667, align: 'left', valign: 'top', margin: [2.0, 2.0, 2.0, 2.0], isTextBox: true, fontSize: 18.0, color: '2E333E', fontFace: 'Arial', lineSpacingMultiple: 1.5 });
  slide.addText('\u2014 Stand first', { x: 1.25, y: 9.349, w: 4.0664, h: 0.3781, align: 'left', valign: 'top', margin: [2.0, 2.0, 2.0, 2.0], isTextBox: true, fontSize: 18.0, charSpacing: 3.6, color: 'D65A1F', fontFace: 'Arial' });
  slide.addShape(pres.shapes.RECTANGLE, { x: 9.9896, y: 4.8021, w: 0.0104, h: 4.8333, fill: { color: '0B1220', transparency: 82.0 }, line: { type: 'none' } });
  slide.addText('Movement 02', { x: 5.625, y: 5.2604, w: 4.0664, h: 0.3781, align: 'left', valign: 'top', margin: [2.0, 2.0, 2.0, 2.0], isTextBox: true, fontSize: 18.0, charSpacing: 3.6, color: '74767B', fontFace: 'Arial' });
  slide.addText('Edge', { x: 5.625, y: 5.8385, w: 4.0664, h: 0.6333, align: 'left', valign: 'top', margin: [2.0, 2.0, 2.0, 2.0], isTextBox: true, fontSize: 39.0, charSpacing: -0.39, italic: true, color: '0B1220', fontFace: 'Arial', lineSpacingMultiple: 1.0 });
  slide.addText('Edges are conversations with the slope. We teach how to listen to one before asking it to carry you.', { x: 5.625, y: 6.6302, w: 4.3146, h: 1.5917, align: 'left', valign: 'top', margin: [2.0, 2.0, 2.0, 2.0], isTextBox: true, fontSize: 18.0, color: '2E333E', fontFace: 'Arial', lineSpacingMultiple: 1.5 });
  slide.addText('\u2014 Feel the edge', { x: 5.625, y: 9.349, w: 4.0664, h: 0.3781, align: 'left', valign: 'top', margin: [2.0, 2.0, 2.0, 2.0], isTextBox: true, fontSize: 18.0, charSpacing: 3.6, color: 'D65A1F', fontFace: 'Arial' });
  slide.addShape(pres.shapes.RECTANGLE, { x: 14.3646, y: 4.8021, w: 0.0104, h: 4.8333, fill: { color: '0B1220', transparency: 82.0 }, line: { type: 'none' } });
  slide.addText('Movement 03', { x: 10.0, y: 5.2604, w: 4.0664, h: 0.3781, align: 'left', valign: 'top', margin: [2.0, 2.0, 2.0, 2.0], isTextBox: true, fontSize: 18.0, charSpacing: 3.6, color: '74767B', fontFace: 'Arial' });
  slide.addText('Flow', { x: 10.0, y: 5.8385, w: 4.0664, h: 0.6333, align: 'left', valign: 'top', margin: [2.0, 2.0, 2.0, 2.0], isTextBox: true, fontSize: 39.0, charSpacing: -0.39, italic: true, color: '0B1220', fontFace: 'Arial', lineSpacingMultiple: 1.0 });
  slide.addText('The turn is not a trick, it is a transfer. Weight, pressure, intention \u2014 all moving together, never in sequence.', { x: 10.0, y: 6.6302, w: 4.3146, h: 1.5917, align: 'left', valign: 'top', margin: [2.0, 2.0, 2.0, 2.0], isTextBox: true, fontSize: 18.0, color: '2E333E', fontFace: 'Arial', lineSpacingMultiple: 1.5 });
  slide.addText('\u2014 Link the line', { x: 10.0, y: 9.349, w: 4.0664, h: 0.3781, align: 'left', valign: 'top', margin: [2.0, 2.0, 2.0, 2.0], isTextBox: true, fontSize: 18.0, charSpacing: 3.6, color: 'D65A1F', fontFace: 'Arial' });
