  s.addText("INBOUND DEMAND", {
    x: 6.94, y: 8.42, w: 3, h: 0.22,
    fontFace: F.mono, fontSize: 9, color: C.muted, charSpacing: 2,
  });
  s.addShape("line", { x: 8.72, y: 8.49, w: 0.3, h: 0,
    line: { color: C.ink, width: 1.2, dashType: "dash" } });
