const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.defineLayout({ name: "ZIPPED_WIDE", width: 20, height: 11.25 });
pres.layout = "ZIPPED_WIDE";
pres.author = "Zipped";
pres.title = "Zipped \u2014 App Design Review";

// ----- Palette -----
